import sys


def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    rows = data[2:2 + r]
    ones = [0] * c
    for row in rows:
        flip = row[0] == '0'
        for j in range(c):
            b = row[j] == '1'
            if flip:
                b = not b
            if b:
                ones[j] += 1
    total = r << (c - 1)
    for j in range(1, c):
        total += max(ones[j], r - ones[j]) << (c - 1 - j)
    print(total)


